// marshalAipsProvenantAipToProvenantAipResponseBody builds a value of type
// *ProvenantAipResponseBody from a value of type *aips.ProvenantAip.
func marshalAipsProvenantAipToProvenantAipResponseBody(v *aips.ProvenantAip) *ProvenantAipResponseBody {
	res := &ProvenantAipResponseBody{
		UUID:          v.UUID,
		Name:          v.Name,
		Status:        v.Status,
		CreatedAt:     v.CreatedAt,
		Profile:       v.Profile,
		OcflObjectKey: v.OcflObjectKey,
	}

	return res
}

